"use client";

import { ScrollArea as ScrollPrimitive } from "@base-ui/react/scroll-area";
import { Select as Primitive } from "@base-ui/react/select";
import type { ComponentProps } from "react";

import { Elevated } from "@/components/ui/elevated";
import { FluidHoverArea } from "@/components/ui/fluid-hover-area";
import { ScrollBar } from "@/components/ui/scroll-area";
import { Icon } from "@/lib/icon-context";
import type { IconComponent } from "@/lib/icon-context";
import { useShape } from "@/lib/shape-context";
import type { ShapeVariant } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import type { SizeVariant } from "@/lib/size-context";
import { useSurface } from "@/lib/surface-context";
import { cn } from "@/lib/utils";

export const Select = Primitive.Root;
export const SelectValue = Primitive.Value;
export const SelectGroup = Primitive.Group;
export const SelectLabel = ({
  className,
  ...props
}: ComponentProps<typeof Primitive.GroupLabel>) => (
  <Primitive.GroupLabel
    className={cn("px-2 py-1.5 text-xs text-muted-foreground", className)}
    {...props}
  />
);
export const SelectTrigger = ({
  className,
  children,
  density,
  shape,
  variant = "bordered",
  icon: LeadingIcon,
  ...props
}: ComponentProps<typeof Primitive.Trigger> & {
  density?: SizeVariant;
  shape?: ShapeVariant;
  variant?: "bordered" | "borderless";
  icon?: IconComponent;
}) => {
  const size = useSize(density);
  const radius = useShape(shape);
  return (
    <Primitive.Trigger
      data-slot="select-trigger"
      className={cn(
        "flex w-full items-center justify-between border outline-none transition-colors duration-(--motion-fast) focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 data-[placeholder]:text-muted-foreground",
        variant === "bordered"
          ? "border-input"
          : "border-transparent hover:bg-foreground/5",
        size.iconClass,
        size.control,
        size.text,
        size.px,
        size.gap,
        radius,
        className
      )}
      {...props}
    >
      {LeadingIcon && <LeadingIcon aria-hidden="true" />}
      <span className="min-w-0 flex-1 truncate text-left">{children}</span>
      <Primitive.Icon>
        <Icon name="chevron-down" />
      </Primitive.Icon>
    </Primitive.Trigger>
  );
};
export const SelectContent = ({
  className,
  children,
  ...props
}: ComponentProps<typeof Primitive.Popup>) => {
  const level = useSurface();
  const shape = useShape();
  return (
    <Primitive.Portal>
      <Primitive.Positioner
        sideOffset={6}
        style={{ zIndex: 50 + level }}
        alignItemWithTrigger={false}
      >
        <Elevated
          offset={2}
          render={
            <Primitive.Popup
              data-slot="select-content"
              className={cn(
                "min-w-(--anchor-width) overflow-hidden border border-border/60 shadow-md origin-(--transform-origin) transition-[opacity,transform] duration-(--motion-moderate) data-[ending-style]:duration-(--motion-exit-moderate) data-[starting-style]:opacity-0 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[ending-style]:scale-95 motion-reduce:transition-none",
                shape,
                className
              )}
              {...props}
            >
              <ScrollPrimitive.Root className="relative overflow-hidden">
                <Primitive.List
                  render={<ScrollPrimitive.Viewport />}
                  className="max-h-[min(300px,var(--available-height))] overscroll-contain outline-none"
                >
                  <FluidHoverArea itemSelector="[role=option]" className="p-1">
                    {children}
                  </FluidHoverArea>
                </Primitive.List>
                <ScrollBar />
              </ScrollPrimitive.Root>
            </Primitive.Popup>
          }
        />
      </Primitive.Positioner>
    </Primitive.Portal>
  );
};
export const SelectItem = ({
  className,
  children,
  icon: ItemIcon,
  ...props
}: ComponentProps<typeof Primitive.Item> & { icon?: IconComponent }) => {
  const size = useSize();
  const shape = useShape();
  return (
    <Primitive.Item
      className={cn(
        "relative flex cursor-default items-center outline-none select-none data-[disabled]:opacity-50 focus-visible:bg-accent focus-visible:ring-1 focus-visible:ring-ring",
        size.control,
        size.text,
        size.gap,
        size.iconClass,
        size.variant === "compact" ? "px-1.5" : "px-2",
        shape,
        className
      )}
      {...props}
    >
      {ItemIcon && <ItemIcon aria-hidden="true" />}
      <Primitive.ItemText className="min-w-0 flex-1 truncate">
        {children}
      </Primitive.ItemText>
      <Primitive.ItemIndicator>
        <Icon name="check" width={size.icon} height={size.icon} />
      </Primitive.ItemIndicator>
    </Primitive.Item>
  );
};

"use client";

import type { useRender } from "@base-ui/react/use-render";
import type { ComponentProps } from "react";

import { RenderDiv } from "@/components/ui/render-element";
import {
  clampSurface,
  surfaceStyle,
  SurfaceProvider,
  useSurface,
} from "@/lib/surface-context";
import { cn } from "@/lib/utils";

export const Elevated = ({
  offset = 1,
  render,
  className,
  style,
  ...props
}: ComponentProps<"div"> & {
  offset?: number;
  render?: useRender.RenderProp;
}) => {
  const level = clampSurface(useSurface() + offset);
  const Component = RenderDiv;
  return (
    <SurfaceProvider value={level}>
      <Component
        render={render}
        data-surface={level}
        className={cn(
          "text-foreground ring-1 ring-border/50 shadow-sm",
          className
        )}
        style={{ ...surfaceStyle(level), ...style }}
        {...props}
      />
    </SurfaceProvider>
  );
};

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { useEffect, useRef } from "react";

import { FluidHoverHighlight } from "@/components/ui/fluid-hover-highlight";
import { useFluidHover } from "@/hooks/use-fluid-hover";
import { cn } from "@/lib/utils";

// Only the moving background is shared. Primitives keep ownership of focus,
// selection and keyboard navigation.
export const FluidHoverArea = ({
  itemSelector,
  axis = "y",
  children,
  className,
  render,
  ref,
  ...props
}: useRender.ComponentProps<"div"> & {
  itemSelector: string;
  axis?: "x" | "y" | "xy";
}) => {
  const container = useRef<HTMLDivElement>(null);
  const hover = useFluidHover(container, { axis, gapClick: false });
  const { registerItem } = hover;
  useEffect(() => {
    const element = container.current;
    if (!element) {
      return;
    }
    let items: HTMLElement[] = [];
    const syncItems = () => {
      const next = [...element.querySelectorAll<HTMLElement>(itemSelector)];
      for (
        let index = 0;
        index < Math.max(items.length, next.length);
        index += 1
      ) {
        registerItem(index, next[index] ?? null);
      }
      items = next;
    };
    syncItems();
    const observer = new MutationObserver(syncItems);
    observer.observe(element, { childList: true, subtree: true });
    return () => {
      observer.disconnect();
      for (const [index] of items.entries()) {
        registerItem(index, null);
      }
    };
  }, [children, itemSelector, registerItem]);
  return useRender({
    props: mergeProps(
      {
        ...hover.handlers,
        children: (
          <>
            <FluidHoverHighlight hover={hover} />
            {children}
          </>
        ),
        className: cn("relative isolate", className),
        onKeyDownCapture: () => hover.setActiveIndex(null),
      },
      props
    ),
    ref: [container, ref ?? null],
    render,
  });
};

"use client";
import { AnimatePresence, motion } from "motion/react";
import type { Transition } from "motion/react";

import type { UseFluidHoverReturn } from "@/hooks/use-fluid-hover";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { motionPresets, motionTransition, spring } from "@/lib/motion";
import { useShape } from "@/lib/shape-context";
import { cn } from "@/lib/utils";

export const FluidHoverHighlight = ({
  hover,
  hidden = false,
  className,
  transition = spring.fast,
}: {
  hover: UseFluidHoverReturn;
  hidden?: boolean;
  className?: string;
  transition?: Transition | false;
}) => {
  const reduced = useReducedMotion();
  const shape = useShape();
  const rect =
    !hidden && hover.isMeasured && hover.activeIndex !== null
      ? hover.itemRects[hover.activeIndex]
      : null;
  const target = rect
    ? { height: rect.height, width: rect.width, x: rect.left, y: rect.top }
    : {};
  return (
    <AnimatePresence>
      {rect && (
        <motion.div
          key={hover.sessionRef.current}
          aria-hidden="true"
          data-slot="fluid-hover-highlight"
          className={cn(
            "pointer-events-none absolute top-0 left-0 bg-(--fluid-hover)",
            shape,
            className
          )}
          initial={{ ...target, opacity: 0 }}
          animate={{ ...target, opacity: 1 }}
          exit={{ opacity: 0, transition: spring.fast.exit }}
          transition={{
            ...motionTransition(
              transition === false ? motionPresets.snap : transition,
              reduced
            ),
            opacity: motionPresets.fade,
          }}
        />
      )}
    </AnimatePresence>
  );
};

"use client";

import { useRender } from "@base-ui/react/use-render";

export const RenderDiv = ({
  render,
  ...props
}: useRender.ComponentProps<"div">) =>
  useRender({ defaultTagName: "div", props, render });
export const RenderSpan = ({
  render,
  ...props
}: useRender.ComponentProps<"span">) =>
  useRender({ defaultTagName: "span", props, render });
export const RenderAnchor = ({
  render,
  ...props
}: useRender.ComponentProps<"a">) =>
  useRender({ defaultTagName: "a", props, render });

"use client";
import { ScrollArea as Primitive } from "@base-ui/react/scroll-area";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import type { ComponentProps } from "react";

import { useMediaQuery } from "@/hooks/use-media-query";
import { useScrollEdges } from "@/hooks/use-scroll-edges";
import { cn } from "@/lib/utils";

const ScrollContext = createContext({ native: false, visible: true });
const SCROLL_LINGER_MS = 600;
const overflowClasses = {
  both: "overflow-auto",
  horizontal: "overflow-x-auto overflow-y-hidden",
  vertical: "overflow-y-auto overflow-x-hidden",
};
const scrollMask = (direction: string, atStart: boolean, atEnd: boolean) =>
  `linear-gradient(to ${direction}, ${atStart ? "black" : "transparent"}, black 24px, black calc(100% - 24px), ${atEnd ? "black" : "transparent"})`;
export interface ScrollAreaProps extends ComponentProps<"div"> {
  orientation?: "vertical" | "horizontal" | "both";
  viewportClassName?: string;
  native?: boolean;
  fade?: boolean;
  visibility?: "auto" | "always" | "hidden";
  label?: string;
}
export const ScrollBar = ({
  className,
  orientation = "vertical",
  ...props
}: ComponentProps<typeof Primitive.Scrollbar>) => {
  const state = useContext(ScrollContext);
  if (state.native) {
    return null;
  }
  return (
    <Primitive.Scrollbar
      data-slot="scroll-area-scrollbar"
      orientation={orientation}
      data-visible={state.visible || undefined}
      className={cn(
        "group/scrollbar pointer-events-none z-20 flex touch-none select-none opacity-0 transition-opacity duration-(--motion-exit-moderate) delay-(--motion-moderate) data-[visible]:pointer-events-auto data-[visible]:opacity-100 data-[visible]:duration-(--motion-moderate) data-[visible]:delay-0",
        orientation === "vertical" ? "h-full w-2.5" : "h-2.5 w-full flex-col",
        className
      )}
      {...props}
    >
      <Primitive.Thumb
        className={cn(
          "relative rounded-full bg-foreground/8 motion-reduce:transition-none transition-[background-color,width,height] duration-(--motion-moderate) group-hover/scrollbar:bg-foreground/12 active:bg-foreground/16",
          orientation === "vertical"
            ? "mx-auto my-1 -translate-x-0.5 w-1 group-hover/scrollbar:w-1.5"
            : "mx-1 my-auto -translate-y-0.5 h-1 group-hover/scrollbar:h-1.5"
        )}
      />
    </Primitive.Scrollbar>
  );
};
export const ScrollArea = ({
  children,
  className,
  viewportClassName,
  orientation = "vertical",
  native = false,
  fade = true,
  visibility = "auto",
  label = "Scrollable content",
  ...props
}: ScrollAreaProps) => {
  const touch = useMediaQuery("(pointer: coarse)");
  const isNative = native || touch;
  const [hovered, setHovered] = useState(false);
  const [scrolling, setScrolling] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const vertical = useScrollEdges();
  const horizontal = useScrollEdges({ orientation: "horizontal" });
  useEffect(
    () => () => {
      if (timer.current) {
        clearTimeout(timer.current);
      }
    },
    []
  );
  const handleScroll = () => {
    setScrolling(true);
    if (timer.current) {
      clearTimeout(timer.current);
    }
    timer.current = setTimeout(() => setScrolling(false), SCROLL_LINGER_MS);
  };
  const verticalRef = vertical.ref;
  const horizontalRef = horizontal.ref;
  const viewportRef = useCallback(
    (node: HTMLDivElement | null) => {
      verticalRef(node);
      horizontalRef(node);
    },
    [verticalRef, horizontalRef]
  );
  const masks = [
    orientation !== "horizontal" &&
      scrollMask("bottom", vertical.atStart, vertical.atEnd),
    orientation !== "vertical" &&
      scrollMask("right", horizontal.atStart, horizontal.atEnd),
  ]
    .filter(Boolean)
    .join(", ");
  const viewportProps = {
    "aria-label": label,
    className: cn(
      "size-full rounded-[inherit] outline-none focus-visible:ring-2 focus-visible:ring-ring",
      viewportClassName
    ),
    "data-slot": "scroll-area-viewport",
    onScroll: handleScroll,
    ref: viewportRef,
    role: "region",
    style: fade ? { maskComposite: "intersect", maskImage: masks } : undefined,
    tabIndex: 0,
  };
  const visible =
    visibility === "always" ||
    (visibility === "auto" && (hovered || scrolling));
  return (
    <ScrollContext.Provider value={{ native: isNative, visible }}>
      {isNative ? (
        <div
          data-slot="scroll-area"
          className={cn("relative overflow-hidden", className)}
          {...props}
        >
          <div
            {...viewportProps}
            className={cn(
              viewportProps.className,
              overflowClasses[orientation]
            )}
          >
            {children}
          </div>
        </div>
      ) : (
        <Primitive.Root
          data-slot="scroll-area"
          className={cn("relative overflow-hidden", className)}
          onPointerEnter={() => setHovered(true)}
          onPointerLeave={() => setHovered(false)}
          {...props}
        >
          <Primitive.Viewport {...viewportProps}>{children}</Primitive.Viewport>
          {orientation !== "horizontal" && <ScrollBar orientation="vertical" />}
          {orientation !== "vertical" && <ScrollBar orientation="horizontal" />}
          <Primitive.Corner />
        </Primitive.Root>
      )}
    </ScrollContext.Provider>
  );
};

"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import type { MouseEvent, PointerEvent, RefObject } from "react";

export interface ItemRect {
  top: number;
  left: number;
  width: number;
  height: number;
}
export interface UseFluidHoverOptions {
  axis?: "x" | "y" | "xy";
  isItemDisabled?: (element: HTMLElement) => boolean;
  gapClick?: boolean | { maxDistance?: number };
}
export const useFluidHover = <T extends HTMLElement>(
  containerRef: RefObject<T | null>,
  { axis = "y", isItemDisabled, gapClick = true }: UseFluidHoverOptions = {}
) => {
  const items = useRef(new Map<number, HTMLElement>());
  const observer = useRef<ResizeObserver | null>(null);
  const frame = useRef<number | null>(null);
  const point = useRef<{ x: number; y: number } | null>(null);
  const sessionRef = useRef(0);
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const [itemRects, setItemRects] = useState<Record<number, ItemRect>>({});
  const [isMeasured, setIsMeasured] = useState(false);
  const disabled = useCallback(
    (element: HTMLElement) =>
      element.matches(":disabled,[aria-disabled=true],[data-disabled]") ||
      element.getClientRects().length === 0 ||
      !!isItemDisabled?.(element),
    [isItemDisabled]
  );
  const measureItems = useCallback(() => {
    const container = containerRef.current;
    if (!container || !container.offsetWidth || !container.offsetHeight) {
      setIsMeasured(false);
      return;
    }
    const bounds = container.getBoundingClientRect();
    const scaleX = bounds.width / container.offsetWidth || 1;
    const scaleY = bounds.height / container.offsetHeight || 1;
    const next: Record<number, ItemRect> = {};
    let nearest: number | null = null;
    let distance = Infinity;
    for (const [index, element] of items.current) {
      if (disabled(element)) {
        continue;
      }
      const rect = element.getBoundingClientRect();
      next[index] = {
        height: rect.height / scaleY,
        left:
          (rect.left - bounds.left) / scaleX +
          container.scrollLeft -
          container.clientLeft,
        top:
          (rect.top - bounds.top) / scaleY +
          container.scrollTop -
          container.clientTop,
        width: rect.width / scaleX,
      };
      if (!point.current) {
        continue;
      }
      const { x, y } = point.current;
      const insideX = x >= rect.left && x <= rect.right;
      const insideY = y >= rect.top && y <= rect.bottom;
      const contains = (axis === "y" || insideX) && (axis === "x" || insideY);
      const dx = x - (rect.left + rect.width / 2);
      const dy = y - (rect.top + rect.height / 2);
      const distances = {
        x: Math.abs(dx),
        xy: Math.hypot(dx, dy),
        y: Math.abs(dy),
      };
      const candidate = contains ? -1 : distances[axis];
      if (candidate < distance) {
        distance = candidate;
        nearest = index;
      }
    }
    setItemRects((previous) =>
      JSON.stringify(previous) === JSON.stringify(next) ? previous : next
    );
    setIsMeasured(true);
    if (point.current) {
      setActiveIndex(nearest);
    }
  }, [containerRef, axis, disabled]);
  const remeasure = useCallback(() => {
    if (frame.current !== null) {
      return;
    }
    frame.current = requestAnimationFrame(() => {
      frame.current = null;
      measureItems();
    });
  }, [measureItems]);
  const registerItem = useCallback(
    (index: number, element: HTMLElement | null) => {
      const previous = items.current.get(index);
      if (previous === element) {
        return;
      }
      if (previous) {
        observer.current?.unobserve(previous);
      }
      if (element) {
        items.current.set(index, element);
        observer.current?.observe(element);
      } else {
        items.current.delete(index);
      }
      remeasure();
    },
    [remeasure]
  );
  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    observer.current = new ResizeObserver(remeasure);
    observer.current.observe(container);
    for (const element of items.current.values()) {
      observer.current.observe(element);
    }
    const mutation = new MutationObserver(remeasure);
    mutation.observe(container, {
      characterData: true,
      childList: true,
      subtree: true,
    });
    container.addEventListener("scroll", remeasure, { passive: true });
    remeasure();
    return () => {
      observer.current?.disconnect();
      observer.current = null;
      mutation.disconnect();
      container.removeEventListener("scroll", remeasure);
      if (frame.current !== null) {
        cancelAnimationFrame(frame.current);
        frame.current = null;
      }
    };
  }, [containerRef, remeasure]);
  useEffect(() => {
    const element =
      activeIndex === null ? null : items.current.get(activeIndex);
    if (!element) {
      return;
    }
    element.dataset.fluidHoverActive = "";
    return () => {
      delete element.dataset.fluidHoverActive;
    };
  }, [activeIndex]);
  const onPointerMove = (event: PointerEvent) => {
    if (event.pointerType !== "touch") {
      point.current = { x: event.clientX, y: event.clientY };
      remeasure();
    }
  };
  const onPointerLeave = () => {
    point.current = null;
    setActiveIndex(null);
  };
  const onClick = (event: MouseEvent) => {
    if (
      !gapClick ||
      !point.current ||
      event.defaultPrevented ||
      !(event.target instanceof Element)
    ) {
      return;
    }
    for (const element of items.current.values()) {
      if (element.contains(event.target)) {
        return;
      }
    }
    if (
      event.target.closest(
        "button,a,input,textarea,select,[contenteditable],[role=button]"
      )
    ) {
      return;
    }
    const element =
      activeIndex === null ? null : items.current.get(activeIndex);
    if (!element || disabled(element)) {
      return;
    }
    const rect = element.getBoundingClientRect();
    const distance = Math.hypot(
      Math.max(rect.left - event.clientX, 0, event.clientX - rect.right),
      Math.max(rect.top - event.clientY, 0, event.clientY - rect.bottom)
    );
    if (
      typeof gapClick === "object" &&
      distance > (gapClick.maxDistance ?? Infinity)
    ) {
      return;
    }
    const activator = element.matches(
      "button,a,[role=tab],[role=menuitem],[role=option]"
    )
      ? element
      : element.querySelector<HTMLElement>("button,a,[role=button]");
    activator?.click();
  };
  return {
    activeIndex,
    handlers: {
      onClick,
      onPointerCancel: onPointerLeave,
      onPointerEnter: (event: PointerEvent) => {
        if (event.pointerType !== "touch") {
          sessionRef.current += 1;
          onPointerMove(event);
        }
      },
      onPointerLeave,
      onPointerMove,
    },
    isMeasured,
    itemRects,
    measureItems,
    registerItem,
    remeasure,
    sessionRef,
    setActiveIndex,
  };
};
export type UseFluidHoverReturn = ReturnType<typeof useFluidHover>;

import { useEffect, useState } from "react";

export const useMediaQuery = (query: string) => {
  const [value, setValue] = useState(false);

  useEffect(() => {
    const onChange = (event: MediaQueryListEvent) => {
      setValue(event.matches);
    };

    const result = matchMedia(query);
    result.addEventListener("change", onChange);
    setValue(result.matches);

    return () => result.removeEventListener("change", onChange);
  }, [query]);

  return value;
};

"use client";

import { useMediaQuery } from "@/hooks/use-media-query";

/** False during SSR and the first hydration render; subscribes after mounting. */
export const useReducedMotion = () =>
  useMediaQuery("(prefers-reduced-motion: reduce)");

"use client";

import { useCallback, useEffect, useState } from "react";

export const useScrollEdges = <T extends HTMLElement = HTMLDivElement>({
  orientation = "vertical",
  threshold = 1,
}: { orientation?: "horizontal" | "vertical"; threshold?: number } = {}) => {
  const [element, setElement] = useState<T | null>(null);
  const [edges, setEdges] = useState({
    atEnd: true,
    atStart: true,
    canScroll: false,
  });
  const update = useCallback(() => {
    if (!element) {
      return;
    }
    const horizontal = orientation === "horizontal";
    const position = horizontal
      ? Math.abs(element.scrollLeft)
      : element.scrollTop;
    const maximum = horizontal
      ? element.scrollWidth - element.clientWidth
      : element.scrollHeight - element.clientHeight;
    const next = {
      atEnd: position >= maximum - threshold,
      atStart: position <= threshold,
      canScroll: maximum > threshold,
    };
    setEdges((previous) =>
      previous.atStart === next.atStart &&
      previous.atEnd === next.atEnd &&
      previous.canScroll === next.canScroll
        ? previous
        : next
    );
  }, [element, orientation, threshold]);
  useEffect(() => {
    if (!element) {
      return;
    }
    const resize = new ResizeObserver(update);
    const observe = () => {
      resize.disconnect();
      resize.observe(element);
      for (const child of element.children) {
        resize.observe(child);
      }
      update();
    };
    const mutation = new MutationObserver(observe);
    mutation.observe(element, {
      characterData: true,
      childList: true,
      subtree: true,
    });
    observe();
    element.addEventListener("scroll", update, { passive: true });
    return () => {
      resize.disconnect();
      mutation.disconnect();
      element.removeEventListener("scroll", update);
    };
  }, [element, update]);
  return { ref: setElement, ...edges, update };
};

